import random


def roll_many(n, sides=6):
    return [random.randint(1, sides) for _ in range(n)]


def play(rolls_a, rolls_b):
    a, b = sum(rolls_a), sum(rolls_b)
    if a > b:
        return "A"
    if b > a:
        return "B"
    return "draw"

alt:
import random


def roll_many(n, sides=6):
    rolls = []
    for _ in range(n):
        rolls.append(random.randint(1, sides))
    return rolls


def play(rolls_a, rolls_b):
    diff = sum(rolls_a) - sum(rolls_b)
    return "A" if diff > 0 else "B" if diff < 0 else "draw"
